input.command:
$base = "D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\data"; @(
  "players",
  "reactions\messages",
  "slack\channels",
  "jobs",
  "training",
  "logs"
) | ForEach-Object {
  $p = Join-Path $base $_;
  if (Test-Path -LiteralPath $p) {
    $n = (Get-ChildItem -LiteralPath $p -File -ErrorAction SilentlyContinue | Measure-Object).Count
    Write-Host "$_ : $n files"
  } else { Write-Host "$_ : MISSING" }
}
# line counts for training/logs
foreach ($f in @("training\utterances.jsonl","training\digs.jsonl","conversations\turns.jsonl","logs\inbound.jsonl","logs\outbound.jsonl")) {
  $fp = Join-Path $base $f
  if (Test-Path -LiteralPath $fp) {
    $lc = (Get-Content -LiteralPath $fp | Measure-Object -Line).Lines
    $sz = (Get-Item -LiteralPath $fp).Length
    Write-Host "$f : $lc lines, $([math]::Round($sz/1KB,1)) KB"
  } else { Write-Host "$f : MISSING" }
}
Write-Host "--- players sample count ---"
(Get-ChildItem -LiteralPath (Join-Path $base "players") -Filter "*.json" -ErrorAction SilentlyContinue | Measure-Object).Count
Write-Host "--- good-examples count ---"
try { (Get-Content (Join-Path $base "reactions\good-examples.json") -Raw | ConvertFrom-Json).count } catch { "n/a" }
Write-Host "--- reactor-index keys ---"
try { ((Get-Content (Join-Path $base "reactions\reactor-index.json") -Raw | ConvertFrom-Json).byUser.PSObject.Properties | Measure-Object).Count } catch { "n/a" }
